<script module lang="ts">
/**
 * Page-level list of form errors after a failed submit (`design/components/error-summary.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/error-summary.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onDestroy } from 'svelte'

import {
  Icon,
  agentMember,
  chooseListItem,
  joinSlot,
  listItems,
  watchEffect,
} from '@polymorph/svelte'
import styles from '@polymorph/recipes/structure/error-summary.module.css'

export interface ErrorSummaryError {
  label: string
  fieldId: string
}

export interface ErrorSummaryProps {
  /**
   * Errors in form order, the navigation order (Stat's rule); an empty list renders nothing.
   */
  errors: ErrorSummaryError[]
  /**
   * Text from the app ("The ticket can't be raised yet"); the vocabulary writes no error copy.
   */
  title: string
}
</script>

<script lang="ts">
let { errors, title }: ErrorSummaryProps = $props()
const joined = joinSlot(undefined, () => ({}))
let list = $state<HTMLElement | null>(null)
let root = $state<HTMLElement | null>(null)
const follow = $derived((event: MouseEvent, fieldId: string) => {
  const control = document.getElementById(fieldId)
  if (control === null) return
  event.preventDefault()
  control.focus()
  control.scrollIntoView({ block: 'nearest' })
})
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const ran = agentMember({
    member: 'ErrorSummary',
    element: () => root,
    state: () => ({ items: listItems(list, styles.link) }),
    actions: {
      choose: { argument: 'id', run: (value) => chooseListItem(list, styles.link, value) },
    },
  })
  release1 = () => {
    ran()
  }
}
watchEffect(effect1)
onDestroy(() => release1?.())
</script>

{@render joined.start?.()
}{#if joined.shown
  }{#if errors.length > 0
    }<div bind:this={root} class={styles.root} role="alert" data-member="error-summary"
      ><span class={styles.glyph}><Icon name="error" size="md" /></span
      ><div class={styles.body}
        ><p class={styles.title}>{title}</p
        ><ul bind:this={list} class={styles.list}
          >{#each errors as error, at (`${at}-${error.fieldId}`)
            }<li
              ><a
                class={styles.link}
                href={`#${error.fieldId}`}
                onclick={(event) => { follow(event, error.fieldId) }}
                >{error.label
              }</a
            ></li
          >{/each
        }</ul
      ></div
    ></div
  >{/if
}{/if
}{@render joined.end?.()}
